import { posts } from "../posts";
import type { Page } from "../search";

// the search index, generated by the site: psyche only searches it
export const GET = () =>
  Response.json([
    {
      href: "/",
      title: "A winter garden",
      body: "Planting through the cold months.",
      section: "Pages",
    },
    ...posts.map((post): Page => ({
      href: `/posts/${post.slug}/`,
      title: post.title,
      body: post.sections.map((section) => `${section.heading}\n${section.text}`).join("\n"),
      authors: post.authors,
      categories: post.categories,
      headings: post.sections.map(({ id, heading }) => ({ value: heading, id })),
      section: "Posts",
    })),
  ] satisfies Page[]);
